using FireSprinkler.Api.Data; using FireSprinkler.Api.Hubs; using FireSprinkler.Api.Models; using Microsoft.AspNetCore.SignalR; using Microsoft.EntityFrameworkCore; using System.Net.Http.Json;
var b=WebApplication.CreateBuilder(args); b.Services.AddDbContext<AppDbContext>(o=>o.UseNpgsql(b.Configuration.GetConnectionString("Default"))); b.Services.AddSignalR(); b.Services.AddEndpointsApiExplorer(); b.Services.AddSwaggerGen(); b.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyHeader().AllowAnyMethod().AllowAnyOrigin())); b.Services.AddHttpClient("analytics",c=>c.BaseAddress=new Uri(b.Configuration["Analytics:BaseUrl"]??"http://localhost:8001")); var app=b.Build(); app.UseCors(); app.UseSwagger(); app.UseSwaggerUI();
using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>(); for(int i=0;i<30;i++){try{await db.Database.EnsureCreatedAsync();await SeedData.EnsureSeeded(db);break;}catch when(i<29){await Task.Delay(2000);}}}
app.MapGet("/api/health",()=>Results.Ok(new{status="healthy"}));
app.MapGet("/api/points",async(AppDbContext db,string? systemType)=>{var q=db.Points.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(systemType))q=q.Where(x=>x.SystemType==systemType.ToUpper());return Results.Ok(await q.OrderBy(x=>x.PointId).ToListAsync());});
app.MapGet("/api/events",async(AppDbContext db,int? limit)=>Results.Ok(await db.Events.AsNoTracking().OrderByDescending(x=>x.OccurredAt).Take(Math.Clamp(limit??100,1,500)).ToListAsync()));
app.MapGet("/api/summary",async(AppDbContext db)=>{var ev=await db.Events.AsNoTracking().Where(x=>x.OccurredAt>=DateTimeOffset.UtcNow.AddHours(-24)).ToListAsync();return Results.Ok(new{totalPoints=await db.Points.CountAsync(),wetPoints=await db.Points.CountAsync(x=>x.SystemType=="WET"),dryPoints=await db.Points.CountAsync(x=>x.SystemType=="DRY"),eventsLast24Hours=ev.Count,alarmEvents=ev.Count(x=>x.Classification=="ALARM"),supervisoryEvents=ev.Count(x=>x.Classification=="SUPERVISORY"),troubleEvents=ev.Count(x=>x.Classification=="TROUBLE"),statusEvents=ev.Count(x=>x.Classification=="STATUS")});});
app.MapPost("/api/events",async(IncomingEvent input,AppDbContext db,IHubContext<MonitoringHub> hub)=>{if(string.IsNullOrWhiteSpace(input.EventId)||string.IsNullOrWhiteSpace(input.PointId)||string.IsNullOrWhiteSpace(input.ObservedValue))return Results.BadRequest(new{error="eventId, pointId and observedValue are required"});if(await db.Events.AnyAsync(x=>x.EventId==input.EventId))return Results.Ok(new{accepted=true,duplicate=true});var point=await db.Points.FirstOrDefaultAsync(x=>x.PointId==input.PointId);if(point is null||!point.Enabled)return Results.BadRequest(new{error="Unknown or disabled point"});var e=new MonitoringEvent{EventId=input.EventId,SourceId=input.SourceId??"UNKNOWN",PointId=input.PointId,ObservedValue=input.ObservedValue,PreviousValue=input.PreviousValue,Classification=point.Classification,Quality=input.Quality??"GOOD",OccurredAt=input.OccurredAt??DateTimeOffset.UtcNow,ReceivedAt=DateTimeOffset.UtcNow,SequenceNumber=input.SequenceNumber};db.Events.Add(e);await db.SaveChangesAsync();await hub.Clients.All.SendAsync("eventReceived",e);return Results.Created($"/api/events/{e.EventId}",new{accepted=true,duplicate=false,eventId=e.EventId,classification=e.Classification});});
app.MapGet("/api/analytics/health",async(IHttpClientFactory f)=>{try{return Results.Ok(await f.CreateClient("analytics").GetFromJsonAsync<object>("/health"));}catch{return Results.Problem("Analytics service unavailable",statusCode:503);}});
app.MapGet("/api/analytics/pressure",async(string pointId,AppDbContext db,IHttpClientFactory f)=>{var rows=await db.Events.AsNoTracking().Where(x=>x.PointId==pointId).OrderBy(x=>x.OccurredAt).Select(x=>new{timestamp=x.OccurredAt,value=x.ObservedValue}).Take(500).ToListAsync();var response=await f.CreateClient("analytics").PostAsJsonAsync("/analyze/states",new{pointId,observations=rows});if(!response.IsSuccessStatusCode)return Results.Problem("Analytics request failed",statusCode:502);return Results.Ok(await response.Content.ReadFromJsonAsync<object>());});
app.MapHub<MonitoringHub>("/hubs/monitoring"); app.Run();
